  function isDirectConversation(c){return Boolean(c&&!c.projectId&&!c.channelId&&c.recipients?.length===1);}
  function directOwner(c){return agentById(c?.recipients?.[0]);}
  function directSubtitle(c,a,duplicate){const last=[...(c.messages||[])].reverse().find(m=>!m.welcome&&typeof m.text==='string'&&m.text.trim());if(last)return last.text.replace(/\s+/g,' ').trim().slice(0,64)+(last.text.trim().length>64?'…':'');if(duplicate&&c.title&&c.title!==a.name)return c.title;return 'New conversation';}
